export async function signIn(
  email: string,
  password: string = env.seedPassword,
  opts: { fresh?: boolean } = {},
): Promise<Session> {
  const file = cacheFile(email, password);
  if (!opts.fresh) {
    const hit = memo.get(file) ?? readCache(file);
    if (hit && (await stillValid(hit))) {
